testcode.text:
const paragraph = document.querySelector('p');
  const button = document.querySelector('button');

  if (typeof window.contar !== 'function') {
    throw new Error('ERRO: A função contar() não foi encontrada.');
  }

  if (paragraph.textContent.trim() !== '0') {
    throw new Error('ERRO: O contador deve começar com o valor 0.');
  }

  button.click();
  if (paragraph.textContent.trim() !== '1') {
    throw new Error('ERRO: Depois de um clique, o valor esperado é 1.');
  }

  button.click();
  if (paragraph.textContent.trim() !== '2') {
    throw new Error('ERRO: Depois de dois cliques, o valor esperado é 2.');
  }

  for (let i = 0; i < 5; i++) {
    button.click();
  }
  if (paragraph.textContent.trim() !== '7') {
    throw new Error('ERRO: Depois de sete cliques, o valor esperado é 7.');
  }

  console.log('CORRETO: O contador funciona corretamente!');

