question.answer:
function hello() {
  const h1 = document.querySelector("h1");
  if (h1.textContent === "Hello!") {
    h1.textContent = "Goodbye!";
    h1.style.color = "green";
  } else {
    h1.textContent = "Hello!";
    h1.style.color = "black";
  }
}

