question.template:
// --- TEMPLATE NodeJS para CodeRunner ---
// simula um "document" com botão e parágrafo

const fakeParagrafo = { textContent: "99" };

const fakeBotao = {
  eventos: {},
  onclick: null,
  addEventListener: function(evento, func) {
    this.eventos[evento] = func;
  },
  click: function() {
    const event = { __called: true };
    if (this.eventos["click"]) this.eventos["click"](event);
    if (this.onclick) this.onclick(event);
  }
};

const fakeDocument = {
  querySelector: function(selector) {
    if (selector.startsWith("#")) {
      const id = selector.slice(1);
      if (id === "botao") return fakeBotao;
      if (id === "contador") return fakeParagrafo;
    }
    if (selector.toLowerCase() === "button") return fakeBotao;
    if (selector.toLowerCase() === "p") return fakeParagrafo;
    return null;
  },
  getElementById: function(id) {
    if (id === "botao") return fakeBotao;
    if (id === "contador") return fakeParagrafo;
    return null;
  }
};

// simular ambiente global
global.document = fakeDocument;

// --- CÓDIGO DO ALUNO ---
{{ STUDENT_ANSWER }}

// --- TESTES AUTOMÁTICOS ROBUSTOS ---

function fail(msg) {
  console.error("❌ TEST FAIL: " + msg);
  process.exit(1);
}
function pass(msg) {
  console.log("✅ TEST PASS: " + msg);
}

// 1️⃣ Verifica se o aluno registou um listener de clique
if (!fakeBotao.eventos["click"]) {
  fail("Nenhum listener de 'click' registado com addEventListener('click', ...).");
}

// 2️⃣ O valor inicial deve ser string e não modificado
if (typeof fakeParagrafo.textContent !== "string") {
  fail("O parágrafo deve ter textContent do tipo string inicialmente.");
}
if (fakeParagrafo.textContent !== "99") {
  fail("O valor inicial do parágrafo foi alterado antes do clique.");
}

// guardar valor inicial
const inicial = parseInt(fakeParagrafo.textContent, 10);

// 3️⃣ Testa primeiro clique
fakeBotao.click();
let atual = fakeParagrafo.textContent;

// 👉 ajustado: aceita string ou número
if (typeof atual !== "string" && typeof atual !== "number") {
  fail("Após 1 clique: textContent deve ser string ou número.");
}

let num1 = parseInt(atual, 10);
if (!Number.isInteger(num1)) fail("Após 1 clique: textContent não é inteiro parseável.");
if (num1 !== inicial - 1) fail(`Após 1 clique: esperado ${inicial - 1}, obteve ${num1}.`);

// 4️⃣ Testa 3 cliques no total
fakeBotao.click();
fakeBotao.click();
let num3 = parseInt(fakeParagrafo.textContent, 10);
if (num3 !== inicial - 3) fail(`Após 3 cliques: esperado ${inicial - 3}, obteve ${num3}.`);


// ✅ Se chegou aqui, passou tudo
pass("Comportamento correcto.");

question.answer:
// seleciona o botão e o parágrafo
const botao = document.querySelector("#botao");
const paragrafo = document.querySelector("#contador");

// quando o botão é clicado
botao.addEventListener("click", function() {
    let contador = Number(paragrafo.textContent)
    paragrafo.textContent = --contador;
});

