// Simulação simples do DOM e fetch (sem conflitos com o código do aluno)
global.__div = { textContent: "" };

global.document = {
  querySelector(selector) {
    if (selector === "div") return __div;
    return null;
  }
};

function fetch(url) {
  if (url === "http://ulusofona.pt/curso?params=alunos") {
    return Promise.resolve({
      ok: true, // ✅ compatível com alunos que verificam response.ok
      status: 200,
      json() {
        return Promise.resolve({
          dia: "2022-06-23",
          alunos: { LP1: 104, LP2: 94, PW: 86 }
        });
      }
    });
  } else {
    return Promise.resolve({
      ok: false, // ✅ caso URL seja desconhecida
      json() {
        return Promise.resolve({});
      }
    });
  }
}

global.fetch = fetch; // 🔧 garante que substitui o fetch global


// --- Código do aluno ---
{{ STUDENT_ANSWER }}
// ------------------------

// Teste: Espera que o <div> contenha o texto correto
setTimeout(() => {
  const esperado = "Alunos inscritos em PW: 86";
  const div = document.querySelector("div"); // obtém a div simulada
  if (div.textContent.trim() === esperado) {
    console.log("Sucesso");
  } else {
    console.log("ERRO: Esperava outro texto: '" + div.textContent + "'");
  }
}, 1000);

