// Variáveis

const url = "http://ulusofona.pt/curso?params=alunos"
const div = document.querySelector("div")


// Recolha de dados
fetch(url)
    .then(response => {
        if(!response.ok) 
            throw new Error(`Erro HTTP: ${response.status}`)

        return response.json()
    })
    .then(data => {

        div.textContent = `Alunos inscritos em PW: ${data.alunos.PW}`;
    })
    .catch(error => console.log(error))
  ;

