    return {
        tagName: tag,
        textContent: "",
        children: [],
        toString() {
            return `<${this.tagName}>${this.textContent}</${this.tagName}>`;
        }
    };
};

let fakeDocument = {
    createdElements: [],
    body: {
        appended: [],
        appendChild(el) {
            this.appended.push(el);
        }
    },
    createElement(tag) {
        const el = fakeElement(tag);
        this.createdElements.push(el);
        return el;
    }
};

global.document = fakeDocument;

// Função do aluno
{{ STUDENT_ANSWER }}

// Testes
olaWeb();

const appended = document.body.appended;

if (appended.length !== 1) {
