question.template:
// Simulação simples do DOM (usando nomes únicos)
const fakeDiv = {
  children: [],
  appendChild(el) {
    this.children.push(el);
  },
  append(el) {
    this.children.push(el);
  }
};


const fakeButton = {
  onclick: null,
  _handlers: {},
  addEventListener(event, fn) {
    if (!this._handlers[event]) this._handlers[event] = [];
    this._handlers[event].push(fn);
  },
  click() {
    // Executa onclick se definido
    if (typeof this.onclick === "function") this.onclick();
    // Executa também event listeners
    if (this._handlers["click"]) {
      this._handlers["click"].forEach(fn => fn());
    }
  }
};


const fakeDocument = {
  querySelector(selector) {
    if (selector === "div") return fakeDiv;
    if (selector === "button") return fakeButton;
    return null;
  },
  createElement(tag) {
    return {
      tagName: tag,
      textContent: "",
    };
  },
  addEventListener(event, fn) {
    if (event === "DOMContentLoaded") {
      fn(); // Executa imediatamente
    }
  }
};

// Simular ambiente global
global.document = fakeDocument;

// Código do aluno
{{ STUDENT_ANSWER }}

// Teste: Simular 3 cliques no botão
fakeButton.click();
fakeButton.click();
fakeButton.click();

// Verificação
if (fakeDiv.children.length !== 3) {
  console.log("ERRO: Esperava 3 elementos <p> inseridos.");
} else if (!fakeDiv.children.every(c =>
  typeof c === "object" &&
  c.tagName === "p" &&
  c.textContent === "Escola difícil, vida fácil"
)) {
  console.log("ERRO: Os elementos inseridos devem ser <p> com o texto correto.");
} else {
  console.log("Sucesso");
}

