// --- TEMPLATE NodeJS para CodeRunner ---
// simula os elementos HTML
const fakeDocument = {
  querySelector: function(selector) {
    if (selector === "img") return fakeImagem;
    if (selector === "#paragrafo" || selector === "p") return fakeParagrafo;
  },
  getElementById: function(id) {
    if (id === "paragrafo") return fakeParagrafo;
  }
};

// objetos simulando os elementos
const fakeParagrafo = { textContent: "" };
const fakeImagem = {
  eventos: {},
  onmouseover: null,
  onmouseout: null,
  addEventListener: function(evento, func) {
    this.eventos[evento] = func;
  },
  dispatchEvent: function(evento) {
    // executa função associada via addEventListener
    if (this.eventos[evento]) this.eventos[evento]();
    // executa função associada via atributo de evento
    if (evento === "mouseover" && typeof this.onmouseover === "function") {
      this.onmouseover();
    }
    if (evento === "mouseout" && typeof this.onmouseout === "function") {
      this.onmouseout();
    }
  }
};

global.document = fakeDocument;

// --- código do aluno inserido aqui ---
{{ STUDENT_ANSWER }}

// --- TESTES AUTOMÁTICOS ---
fakeImagem.dispatchEvent("mouseover");
console.log(fakeParagrafo.textContent); // deve imprimir "rato por cima"

fakeImagem.dispatchEvent("mouseout");
console.log(fakeParagrafo.textContent); // deve imprimir linha vazia

question.answer:
// seleciona a imagem e o parágrafo
const imagem = document.querySelector("img");
const paragrafo = document.querySelector("#paragrafo");

// quando o rato passa por cima da imagem
imagem.addEventListener("mouseover", function() {
    paragrafo.textContent = "rato por cima";
});

// quando o rato sai de cima da imagem
imagem.addEventListener("mouseout", function() {
    paragrafo.textContent = "";
});

