// --- Simulação simples do DOM ---
const fakeUL = { children: [], appendChild(el) { this.children.push(el); } , append(el) { this.children.push(el); } };

const fakeDocument = {
  querySelector(selector) {
    if (selector === "#previsao" || selector === "ul") return fakeUL;
    return null;
  },
  createElement(tag) {
    return { tagName: tag.toUpperCase(), textContent: "" }; // necessário para li
  }
