  return Promise.resolve({
    ok: true,
    json: () => Promise.resolve(fakeAPI)
  });
};

// --- Código do aluno ---
{{ STUDENT_ANSWER }}

// --- Testes automáticos com delay ---
setTimeout(() => {
  const previsoesEsperadas = fakeAPI["Lisboa"];

  if (fakeUL.children.length !== previsoesEsperadas.length) {
    console.log(`ERRO: Esperava ${previsoesEsperadas.length} elementos <li>, mas encontrou ${fakeUL.children.length}.`);
    process.exit(0);
  }

  for (let i = 0; i < previsoesEsperadas.length; i++) {
    const li = fakeUL.children[i];
    const esperado = `${previsoesEsperadas[i].dia}: ${previsoesEsperadas[i].temp} C`;
    if (li.textContent !== esperado) {
