// Variáveis

const url = "http://ipma.pt/previsao"
const ul = document.querySelector("ul")


// Recolha de dados
fetch(url)
    .then(response => {
        if(!response.ok) 
            throw new Error(`Erro HTTP: ${response.status}`)

        return response.json()
    })
    .then(data => {

        data['Lisboa'].forEach(dia => {
          const li = document.createElement('li')
          li.textContent = `${dia.dia}: ${dia.temp} C`; 
          ul.appendChild(li);
        });
    })
    .catch(error => console.log(error));

question.template:
// ------------------------
// Simulação simples do DOM e eventos
// ------------------------
const div__ = {
  // Método que simula addEventListener do DOM
  addEventListener(event, fn) {
    // Guarda a função passada para ser chamada quando o evento acontecer
    this.mouseOverHandler = fn;
  },

  // 👇 Setter para onmouseover
  // Permite associar diretamente uma função ao evento mouseover usando a propriedade
  // Ex: div__.onmouseover = minhaFuncao;
  set onmouseover(fn) {
    // Armazena a função na propriedade interna
    this.mouseOverHandler = fn;
  },

  // Método que simula a ocorrência do evento mouseover
  triggerMouseOver() {
    // Se uma função foi registrada, executa-a
    if (this.mouseOverHandler) this.mouseOverHandler();
  }
};

// ------------------------
// Simulação de parte do DOM global
// ------------------------
global.document = {
  querySelector(selector) {
    // Retorna nosso 'div__' se o seletor for "div"
    if (selector === "div") return div__;
    return null;
  }
};

// Para simplificar, associamos div__ a uma variável global 'div'
global.div = div__;

// ------------------------
// Interceptar alert para teste
// ------------------------
// Em vez de abrir um pop-up, guardamos as mensagens em um array
// Isso permite testar se o código do aluno está correto
global.alertMessages = [];
global.alert = (msg) => global.alertMessages.push(msg);

// ------------------------
// Código do aluno vai aqui
// ------------------------
{{ STUDENT_ANSWER }}

// ------------------------
// Teste: Simular evento mouseover
// ------------------------
div__.triggerMouseOver(); 
// → Executa a função registrada via addEventListener ou setter

// ------------------------
// Verificação automática
// ------------------------
if (global.alertMessages.length !== 1) {
  console.log("ERRO: O alert não foi chamado."); // O aluno não registrou a função corretamente
} else if (global.alertMessages[0] !== "Rato, cuidado com o gato!") {
  console.log("ERRO: A mensagem do alert está incorreta."); // Mensagem não corresponde ao esperado
} else {
  console.log("Sucesso"); // Tudo correto
}

// --- Simulação simples do DOM ---

const fakeP = { textContent: "" };

const fakeInput = {
  value: "",
  onkeyup: null,
  _handlers: {},
  addEventListener(event, fn) {
    if (!this._handlers[event]) this._handlers[event] = [];
    this._handlers[event].push(fn);
  },
  // Simular digitar uma tecla
  keyup() {
    // executa handler direto (onkeyup)
    if (typeof this.onkeyup === "function") this.onkeyup();
    // executa event listeners
    if (this._handlers["keyup"]) {
      this._handlers["keyup"].forEach(fn => fn());
    }
  }
};

const fakeDocument = {
  querySelector(selector) {
    if (selector === "input") return fakeInput;
    if (selector === "p") return fakeP;
    return null;
  },
  addEventListener(event, fn) {
    if (event === "DOMContentLoaded") fn(); // executa de imediato
  }
};

// Simular ambiente global
global.document = fakeDocument;

// --- Código do aluno ---
{{ STUDENT_ANSWER }}

// --- Testes automáticos ---

// Simular digitar três valores diferentes
const testValues = ["Olá", "Teste", "123"];

for (const val of testValues) {
  fakeInput.value = val;
  fakeInput.keyup();

  if (fakeP.textContent !== val) {
    console.log(`ERRO: Esperava que <p> mostrasse "${val}", mas mostra "${fakeP.textContent}".`);
    process.exit(0);
  }
}

console.log("Sucesso");

